mapper.update:
update INTERF_TRAD_REPOASST
secname= #{secname,jdbcType=VARCHAR}, facetotalamt= #{facetotalamt,jdbcType=VARCHAR}, convrate= #{convrate,jdbcType=VARCHAR}, dealamt= #{dealamt,jdbcType=VARCHAR}, ourdepositaccountnumber= #{ourdepositaccountnumber,jdbcType=VARCHAR}, seq_no= #{seqNo,jdbcType=VARCHAR},
where tradeid = #{tradeid,jdbcType=VARCHAR} and secid = #{secid,jdbcType=VARCHAR}

mapper.select:
select reg.trade_date as tradeDate,
reg.finprod_id as finprodId,
reg.trade_market as tradeMarket,
reg.ps as ps,
reg.settle_speed as settleSpeed,
reg.sec_manage_acct_id as secManageAcctId,
reg.yield as tradeYield,
reg.face_value as faceValue,
reg.settle_date as settleDate,
reg.delivery_type as deliveryType,
reg.finprod_type2  as finprodType2,
fp.finprod_market_id as finprodMarketId,
reg.totle_trade_id as totleTradeId
from reg_fin_product_deal_total reg
left join fin_product fp
on reg.finprod_id=fp.finprod_id
where reg.trade_market='01'

    and reg.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR}


    and reg.finprod_type2 = #{finprodType2}


    and reg.trade_date = #{tradeDate}


    and fp.finprod_market_id = #{finprodMarketId}


    and reg.ps = #{ps}


    and reg.settle_date = #{settleSpeed}


    and reg.sec_manage_acct_id = #{secManageAcctId}


    and (to_char(reg.yield,'FM990.9999')=#{tradeYield}
    or to_char(reg.yield)=#{tradeYield})


    and (to_char(reg.face_value,'FM9999999999999990.999999')=#{faceValue}
    or to_char(reg.face_value)=#{faceValue})


    and reg.settle_date = #{settleDate}


    and reg.delivery_type = #{deliveryType}
